def cache_sim(capacity, ttl, ops):
    # Dictionary to store cache entries: {key: (value, write_time)}
    cache = {}
    # OrderedDict-like tracking of access order (most recent at end)
    access_order = []
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries before checking capacity
            cache = {k: v for k, v in cache.items() if v[1] + ttl > t}
            access_order = [k for k in access_order if k in cache]

            # If key already exists, remove it from access_order
            if key in cache:
                access_order.remove(key)
            else:
                # Key is new - check if we need to evict
                if len(cache) >= capacity:
                    # Evict least recently used
                    lru_key = access_order.pop(0)
                    del cache[lru_key]

            # Add/update the entry
            cache[key] = (value, t)
            access_order.append(key)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            cache = {k: v for k, v in cache.items() if v[1] + ttl > t}
            access_order = [k for k in access_order if k in cache]

            if key in cache:
                # Found - return value and make most recently used
                value, _ = cache[key]
                access_order.remove(key)
                access_order.append(key)
                results.append(value)
            else:
                # Not found or expired
                results.append(-1)

    return results

